insert into public.agents(agent_key,name,description,purpose,status,tools) values ('orchestrator','Orchestrator Agent','Coordinates multi-agent workflows and routes work to specialists.','Decide which agents run, in what order, and under which constraints.','disabled',array['task.route','workflow.compose','run.track']),('research','Research Agent','Searches the web and gathers candidate information into a research sandbox.','Collect candidate material into the research sandbox.','disabled',array['web.search','url.fetch','sandbox.write']),('verification','Verification Agent','Checks claims, sources, dates, contradictions and evidence quality.','Evaluate evidence and flag contradictions.','enabled',array['research.read','sources.compare','evidence.evaluate']),('knowledge-acquisition','Knowledge Acquisition Agent','Ingests source text and prepares governed candidate knowledge.','Turn external sources into structured candidates for review.','enabled',array['source.parse','claims.extract','entities.extract','relations.extract','knowledge.compare','candidate.write']),('curator','Knowledge Curator','Governs candidate knowledge and publishes only explicitly approved material.','Publish only explicitly approved, verified knowledge.','enabled',array['verified.read','knowledge.review','knowledge.write','knowledge.version','knowledge.rollback']),('report','Report / PDF Agent','Builds deterministic review reports from verified research.','Produce durable private reports from verified research.','enabled',array['verified.read','pdf.generate','archive.write','report.download.authorize']),('notification','Notification & Delivery Agent','Delivers durable in-app and provider-backed notifications.','Notify the correct recipient about real events only.','enabled',array['notify.create','notify.queue','notify.deliver','notify.preferences','notify.audit']),('security','Security & Compliance Agent','Monitors permission boundaries and policy violations.','Detect and flag violations; backend authorization remains authoritative.','disabled',array['security.inspect','violations.flag']),('optimization','Optimization Agent','Analyses real performance telemetry and recommends improvements.','Recommend measured improvements; never self-apply controlled changes.','disabled',array['telemetry.read','recommendations.write']),('module','Module Agent','Helps create and manage structured application and game modules in sandbox form.','Draft modules inside bounded sandbox boundaries.','disabled',array['modules.read','modules.draft']) on conflict(agent_key) do nothing;
insert into public.agent_permissions(agent_id,permission,allowed,requires_approval) select a.id,p.permission,p.allowed,p.requires_approval from public.agents a join (values ('orchestrator','tasks.route',true,false),('orchestrator','workflows.compose',true,false),('orchestrator','agent.handoff',true,false),('orchestrator','agent.message.send',true,false),('orchestrator','sandbox.open',true,false),('orchestrator','knowledge.publish',false,false),('orchestrator','roles.modify',false,false),('orchestrator','permissions.self_modify',false,false),('research','web.search',true,false),('research','sources.read',true,false),('research','research_sandbox.write',true,false),('research','agent.message.send',true,false),('research','sandbox.open',true,false),('research','knowledge.publish',false,false),('research','roles.modify',false,false),('verification','research.read',true,false),('verification','evidence.evaluate',true,false),('verification','contradictions.flag',true,false),('verification','agent.message.send',true,false),('verification','sandbox.open',true,false),('verification','knowledge.publish',false,false),('verification','roles.modify',false,false),('knowledge-acquisition','sources.ingest',true,false),('knowledge-acquisition','candidates.write',true,false),('knowledge-acquisition','agent.message.send',true,false),('knowledge-acquisition','sandbox.open',true,false),('knowledge-acquisition','knowledge.publish',false,false),('knowledge-acquisition','roles.modify',false,false),('curator','knowledge.transform',true,false),('curator','knowledge.publish',true,true),('curator','knowledge.rollback',true,true),('curator','agent.message.send',true,false),('curator','sandbox.open',true,false),('curator','roles.modify',false,false),('report','research.verified.read',true,false),('report','reports.generate',true,false),('report','agent.message.send',true,false),('report','sandbox.open',true,false),('report','knowledge.approve',false,false),('report','roles.modify',false,false),('notification','notifications.create',true,false),('notification','notifications.queue',true,false),('notification','notifications.deliver',true,false),('notification','notifications.preferences',true,false),('notification','agent.message.send',true,false),('notification','sandbox.open',true,false),('notification','notifications.cross_user',false,false),('notification','roles.modify',false,false),('security','security.inspect',true,false),('security','violations.flag',true,false),('security','agent.message.send',true,false),('security','security.audit.delete',false,false),('security','security.permissions.self_modify',false,false),('security','security.roles.modify',false,false),('optimization','telemetry.read',true,false),('optimization','recommendations.write',true,false),('optimization','agent.message.send',true,false),('optimization','sandbox.open',true,false),('optimization','config.auto_apply',false,true),('optimization','roles.modify',false,false),('module','modules.read',true,false),('module','modules.draft.write',true,false),('module','agent.message.send',true,false),('module','sandbox.open',true,false),('module','modules.execute',false,true),('module','roles.modify',false,false)) p(agent_key,permission,allowed,requires_approval) on p.agent_key=a.agent_key on conflict(agent_id,permission) do nothing;
insert into public.agent_versions(agent_id,version,lifecycle_state,definition,config_hash) select a.id,'1.0.0',case when a.status='enabled' then 'active' when a.status='maintenance' then 'maintenance' else 'disabled' end,jsonb_build_object('agent_id','agent_'||a.agent_key,'version','1.0.0','name',a.name,'description',a.description,'purpose',a.purpose,'mission',a.purpose,'status',a.status::text,'tools',a.tools,'responsibilities',a.tools,'prohibited',jsonb_build_array('Bypass authorization','Modify roles','Self-escalate permissions'),'allowed_inputs',jsonb_build_array('task_context','previous_results'),'expected_outputs',jsonb_build_array('result','status','requires_review'),'quality_requirements',jsonb_build_array('structured output','source traceability where applicable','no silent production writes'),'timeout_policy',jsonb_build_object('timeoutMs',300000,'maxRetries',3,'backoffMs',5000,'escalateOnFailure',true,'escalateTo','admin'),'retry_policy',jsonb_build_object('timeoutMs',300000,'maxRetries',3,'backoffMs',5000,'escalateOnFailure',true,'escalateTo','admin'),'escalation_policy',jsonb_build_object('timeoutMs',300000,'maxRetries',2,'backoffMs',5000,'escalateOnFailure',true,'escalateTo','admin'),'schedule_configuration',jsonb_build_object('enabled',false),'telemetry_configuration',jsonb_build_object('collectMetrics',true,'collectTimeline',true,'retainDays',90)),md5(a.agent_key||':1.0.0:'||a.updated_at::text) from public.agents a on conflict(agent_id,version) do nothing;
